  void HandleDamagePlacement(Rect rect){
   var e=Event.current;if(!damagePainting||generationJob!=null||mesh==null||preview==null||e.type!=EventType.MouseDown||e.button!=0||!e.control)return;
   e.Use();try{
    RebirthFaceGeneratorWindow.ConfigurePreview(preview,orbit,zoom,false,null,mesh.bounds.center+previewOffset);preview.camera.aspect=rect.width/rect.height;
    Ray ray=preview.camera.ViewportPointToRay(new Vector3((e.mousePosition.x-rect.x)/rect.width,1-(e.mousePosition.y-rect.y)/rect.height,0));
    Vector3 point,normal;if(!RebirthBodyDamagePlacement.Pick(mesh,ray,out point,out normal)){status="Click the visible body surface";return;}
    var edited=JsonUtility.FromJson<BodyDamageSettings>(JsonUtility.ToJson(recipe.damage));bool blood=damageChannel==4;string previous=blood?edited.bloodMaskGuid:edited.injuryMaskGuid;
    string guid=RebirthBodyDamagePlacement.Stamp(mesh,point,normal,damageRadius,damageOpacity,previous,blood?0:damageChannel,damageErase,damageShape,damageRotation,damageAspect);if(guid==previous){status="Coverage unchanged";return;}
    if(blood)edited.bloodMaskGuid=guid;else edited.injuryMaskGuid=guid;
    if(!damageErase){if(blood&&edited.blood==0)edited.blood=1;else if(damageChannel==0&&edited.bruising==0)edited.bruising=1;else if(damageChannel==1&&edited.abrasion==0)edited.abrasion=1;else if(damageChannel==2&&edited.cuts==0)edited.cuts=1;else if(damageChannel==3&&edited.decay==0)edited.decay=1;}
    Undo.RecordObject(this,"Place body damage");recipe.damage=edited;Rebuild();EditorUtility.SetDirty(this);status="Saved coverage stamp; Ctrl + Z restores the previous map";
   }catch(Exception ex){status=ex.Message;}Repaint();
  }
