    bool enabled=EditorGUILayout.Toggle("Place deep wounds",deepPainting);if(enabled&&!deepPainting)damagePainting=false;deepPainting=enabled;
    if(deepPainting){newDeepWidth=EditorGUILayout.Slider("New width (m)",newDeepWidth,.008f,.12f);newDeepHeight=EditorGUILayout.Slider("New height (m)",newDeepHeight,.012f,.24f);newDeepDepth=EditorGUILayout.Slider("New depth (m)",newDeepDepth,.002f,.05f);EditorGUILayout.LabelField("Ctrl-click to add a wound. Drag normally to orbit. Up to four separated wounds; oversized/deep placements are refused.",EditorStyles.wordWrappedMiniLabel);}
    var next=RebirthBodyDeepWoundControls.Draw(recipe.damage,ref selectedDeep);if(next!=null)ApplyDeepChange(next);if(recipe.damage.deepWounds.Length>0&&GUILayout.Button("Focus selected wound")){var hit=new BodyWoundSurface(mesh).Locate(recipe.damage.deepWounds[Mathf.Clamp(selectedDeep,0,recipe.damage.deepWounds.Length-1)],recipe.height);previewOffset=hit.point-mesh.bounds.center;orbit=new Vector2(Mathf.Atan2(hit.normal.x,hit.normal.z)*Mathf.Rad2Deg,Mathf.Clamp(Mathf.Asin(Mathf.Clamp(hit.normal.y,-1,1))*Mathf.Rad2Deg,-70,70));var wound=recipe.damage.deepWounds[Mathf.Clamp(selectedDeep,0,recipe.damage.deepWounds.Length-1)];zoom=Mathf.Max(.04f,Mathf.Max(wound.width,wound.height)*.8f);Repaint();}
   }
  }
  void ApplyDeepChange(BodyDamageSettings next){bool previousMatch=previewMatchesRecipe;var previous=recipe.damage;Undo.RecordObject(this,"Deep wounds");recipe.damage=next;Rebuild();if(!string.IsNullOrEmpty(status)){recipe.damage=previous;previewMatchesRecipe=previousMatch;}EditorUtility.SetDirty(this);}
  void HandleDeepPlacement(Rect rect){var e=Event.current;if(!deepPainting||generationJob!=null||mesh==null||preview==null||e.type!=EventType.MouseDown||e.button!=0||!e.control)return;e.Use();try{if(recipe.damage.deepWounds.Length>=RebirthBodyDeepWounds.Maximum)throw new InvalidOperationException("Remove a wound before adding another");RebirthFaceGeneratorWindow.ConfigurePreview(preview,orbit,zoom,false,null,mesh.bounds.center+previewOffset);preview.camera.aspect=rect.width/rect.height;var ray=preview.camera.ViewportPointToRay(new Vector3((e.mousePosition.x-rect.x)/rect.width,1-(e.mousePosition.y-rect.y)/rect.height,0));var wound=RebirthBodyDeepWounds.Place(mesh,ray,recipe.height);wound.width=newDeepWidth;wound.height=newDeepHeight;wound.depth=newDeepDepth;var next=JsonUtility.FromJson<BodyDamageSettings>(JsonUtility.ToJson(recipe.damage));next.deepWounds=next.deepWounds.Concat(new[]{wound}).ToArray();ApplyDeepChange(next);selectedDeep=Mathf.Clamp(next.deepWounds.Length-1,0,Mathf.Max(0,recipe.damage.deepWounds.Length-1));}catch(Exception ex){status=ex.Message;}Repaint();}
  void DrawDamageControls(){
   EditorGUILayout.Space();EditorGUILayout.LabelField("Zombie skin damage",EditorStyles.boldLabel);DrawDamagePlacementControls();DrawDeepPlacementControls();
   using(new EditorGUI.DisabledScope(generationJob!=null))try{if(recipe.damage==null)recipe.damage=new BodyDamageSettings();var next=RebirthBodyDamage.Draw(recipe.damage);if(next!=null){Undo.RecordObject(this,"Body damage");recipe.damage=next;Rebuild();EditorUtility.SetDirty(this);}}catch(Exception e){EditorGUILayout.HelpBox(e.Message,MessageType.Error);if(GUILayout.Button("Reset damage maps")){Undo.RecordObject(this,"Reset damage maps");recipe.damage=new BodyDamageSettings();Rebuild();EditorUtility.SetDirty(this);}}
  }
  void Save(){try{if(!previewMatchesRecipe)throw new InvalidOperationException("Resolve the body preview error before saving");string path=EditorUtility.SaveFilePanelInProject("Save body settings",recipe.name,"json","");if(string.IsNullOrEmpty(path))return;recipe.Validate(template);File.WriteAllText(path,JsonUtility.ToJson(recipe,true));AssetDatabase.ImportAsset(path);status="Body settings saved";}catch(Exception e){status=e.Message;}}
  void Load(){try{string path=EditorUtility.OpenFilePanel("Load body settings",Application.dataPath,"json");if(string.IsNullOrEmpty(path))return;var next=JsonUtility.FromJson<BodyRecipe>(File.ReadAllText(path));next.Validate(template);Undo.RecordObject(this,"Load body settings");recipe=next;beforeGeneration=null;referenceImage=null;skinHeadSettings=null;Rebuild();RestoreInputReferences();}catch(Exception e){status=e.Message;}}
  void Export(){try{if(!previewMatchesRecipe)throw new InvalidOperationException("Resolve the body preview error before exporting");string path=EditorUtility.SaveFilePanelInProject("Export body",recipe.name,"prefab","");if(!string.IsNullOrEmpty(path))status=RebirthBodyExporter.Export(template,recipe,path);}catch(Exception e){status=e.Message;}}

 }
